package com.yeyamo_mobile.api.recommendation_service.application.scoring;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.recommendation_service.domain.*;
@Component public class ProximityScoringStrategy implements ScoringStrategy{public String name(){return"proximity";}public double score(Candidate c,RecommendationProfile p,RecommendationContext x){if(!p.locationSharingEnabled()||x.latitude()==null||c.latitude()==null)return 0;double d=distance(x.latitude(),x.longitude(),c.latitude(),c.longitude());return Math.max(0,25*(1-d/200));}static double distance(double a,double b,double c,double d){double r=6371,p1=Math.toRadians(a),p2=Math.toRadians(c),dp=Math.toRadians(c-a),dl=Math.toRadians(d-b);double h=Math.sin(dp/2)*Math.sin(dp/2)+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)*Math.sin(dl/2);return 2*r*Math.asin(Math.sqrt(h));}}
